external::restaurants.flatMap((restaurant) => restaurant.items.flatMap((item) => {
      const logicalKey = `${restaurant.id}:${item.optionGroupKey || item.id}`;
      if (seen.has(logicalKey)) return [];
      const variants = item.optionGroupKey ? restaurant.items.filter((candidate) => candidate.optionGroupKey === item.optionGroupKey) : [item];
      const matches = variants.some((variant) => [variant.displayName, variant.name, variant.description, variant.category]
        .filter(Boolean).some((value) => value!.toLocaleLowerCase().includes(normalized)));
      if (!matches) return [];
      seen.add(logicalKey);
      const lowest = [...variants].sort((a, b) => a.price - b.price)[0];
      return [{ restaurant, item: lowest, name: lowest.displayName || lowest.name, customizable: variants.length > 1 }];
    })).slice

